import { initializeApp } from 'firebase/app';
import { getDatabase } from 'firebase/database';
import { firebaseConfig } from '../constants';

// Firebase 应用初始化（全局单例）
export const app = initializeApp(firebaseConfig);
export const db = getDatabase(app);

// 路径构建辅助函数——避免在组件中硬编码路径，未来加用户权限时只需改这里
export const paths = {
  project: (projectName) => `projects/${projectName}`,
  stops: (projectName) => `projects/${projectName}/stops`,
  phaseReturns: (projectName) => `projects/${projectName}/phaseReturns`,
  calendarNotes: (projectName) => `projects/${projectName}/calendarNotes`,
  projectList: 'projects',
  systemConfig: 'systemConfig',
  passwords: 'systemConfig/passwords',
};
