import { ref, onValue, set, push, update, remove, get } from 'firebase/database';
import { db } from './firebase';

/**
 * 数据访问层（Data Access Layer）
 *
 * 封装所有数据库操作，App.js 和 hooks 不直接依赖 Firebase API。
 * 未来切换数据库（如 LeanCloud / 腾讯云开发）只需修改此文件，
 * 上层代码零改动。
 *
 * 设计原则：
 * 1. 低-level 通用方法：watch / setData / pushData / updateData / removeData / batchUpdate
 * 2. 高-level 语义化方法：addStop / updateStop / removeStop / createProject 等
 * 3. 所有方法返回 Promise（除 watch 返回取消监听函数）
 */

// ============================================================
// 低-level 通用方法
// ============================================================

/**
 * 实时监听路径数据变化
 * @param {string} path - 数据库路径
 * @param {Function} callback - 回调函数，接收解析后的原始数据（可能为 null）
 * @returns {Function} 取消监听函数
 */
export function watch(path, callback) {
  return onValue(ref(db, path), (snap) => {
    callback(snap.val());
  });
}

/**
 * 写入/覆盖数据
 * @param {string} path - 数据库路径
 * @param {*} data - 要写入的数据
 */
export function setData(path, data) {
  return set(ref(db, path), data);
}

/**
 * 生成唯一ID（不写入数据，仅返回ID）
 * 用于需要先拿到ID再构建批量更新的场景
 * @param {string} path - 父路径
 * @returns {string} 唯一ID
 */
export function generateId(path) {
  return push(ref(db, path)).key;
}

/**
 * 新增数据（自动生成唯一ID并写入）
 * @param {string} path - 父路径
 * @param {*} data - 要写入的数据
 * @returns {Promise<string>} 新生成的ID
 */
export function pushData(path, data) {
  const newRef = push(ref(db, path));
  return set(newRef, data).then(() => newRef.key);
}

/**
 * 部分更新数据（合并写入，不覆盖其他字段）
 * @param {string} path - 数据库路径
 * @param {Object} data - 要更新的字段
 */
export function updateData(path, data) {
  return update(ref(db, path), data);
}

/**
 * 删除数据
 * @param {string} path - 数据库路径
 */
export function removeData(path) {
  return remove(ref(db, path));
}

/**
 * 批量多路径原子更新
 * @param {Object} updates - { "path1": data1, "path2": data2, ... }
 */
export function batchUpdate(updates) {
  return update(ref(db), updates);
}

/**
 * 一次性读取数据（非实时）
 * @param {string} path - 数据库路径
 * @returns {Promise<*>} 读取到的数据
 */
export function getData(path) {
  return get(ref(db, path)).then(snap => snap.val());
}

// ============================================================
// 高-level 语义化方法 —— 项目管理
// ============================================================

/** 创建新项目（仅写入 created 时间戳） */
export function createProject(name) {
  return setData(`projects/${name}/created`, Date.now());
}

/** 重命名项目（将旧项目数据复制到新名称，删除旧项目） */
export function renameProject(oldName, newName, data) {
  return Promise.all([
    setData(`projects/${newName}`, data),
    removeData(`projects/${oldName}`)
  ]);
}

/** 复制项目（将元数据复制到新项目） */
export function duplicateProject(sourceName, newName, metadata) {
  return setData(`projects/${newName}`, { ...metadata, created: Date.now() });
}

/** 删除项目 */
export function deleteProject(name) {
  return removeData(`projects/${name}`);
}

// ============================================================
// 高-level 语义化方法 —— 站点管理
// ============================================================

/** 添加站点（自动生成ID） */
export function addStop(project, stop) {
  return pushData(`projects/${project}/stops`, stop);
}

/** 更新站点部分字段 */
export function updateStop(project, stopId, data) {
  return updateData(`projects/${project}/stops/${stopId}`, data);
}

/** 删除站点 */
export function removeStop(project, stopId) {
  return removeData(`projects/${project}/stops/${stopId}`);
}

/** 覆盖整个站点列表（用于撤销操作） */
export function setStops(project, stops) {
  return setData(`projects/${project}/stops`, stops);
}

/** 清空所有站点 */
export function clearStops(project) {
  return removeData(`projects/${project}/stops`);
}

// ============================================================
// 高-level 语义化方法 —— 返程点管理
// ============================================================

/** 设置/覆盖阶段返程点 */
export function setPhaseReturn(project, phase, data) {
  return setData(`projects/${project}/phaseReturns/${phase}`, data);
}

/** 更新返程点部分字段 */
export function updatePhaseReturn(project, phase, data) {
  return updateData(`projects/${project}/phaseReturns/${phase}`, data);
}

/** 删除阶段返程点 */
export function removePhaseReturn(project, phase) {
  return removeData(`projects/${project}/phaseReturns/${phase}`);
}

/** 覆盖所有返程点（用于撤销操作） */
export function setPhaseReturns(project, returns) {
  return setData(`projects/${project}/phaseReturns`, returns);
}

/** 清空所有返程点 */
export function clearPhaseReturns(project) {
  return removeData(`projects/${project}/phaseReturns`);
}

// ============================================================
// 高-level 语义化方法 —— 标签偏移
// ============================================================

/** 更新站点标签拖动偏移量 */
export function updateLabelOffset(project, stopId, offset) {
  return updateData(`projects/${project}/stops/${stopId}/labelOffset`, offset);
}

/** 重置站点标签偏移量到原点 */
export function resetLabelOffset(project, stopId) {
  return updateData(`projects/${project}/stops/${stopId}/labelOffset`, { x: 0, y: 0 });
}

// ============================================================
// 高-level 语义化方法 —— 系统配置
// ============================================================

/** 更新密码配置 */
export function updatePasswords(data) {
  return updateData('systemConfig/passwords', data);
}

// ============================================================
// 实时监听便捷方法
// ============================================================

export function watchProjects(callback) {
  return watch('projects', callback);
}

export function watchStops(project, callback) {
  return watch(`projects/${project}/stops`, callback);
}

export function watchPhaseReturns(project, callback) {
  return watch(`projects/${project}/phaseReturns`, callback);
}

export function watchCalendarNotes(project, callback) {
  return watch(`projects/${project}/calendarNotes`, callback);
}

export function watchPasswords(callback) {
  return watch('systemConfig/passwords', callback);
}
