import { CHINESE_HOLIDAYS } from '../constants';

// 获取今天的日期字符串 YYYY-MM-DD
export const getToday = () => {
  const d = new Date();
  const yy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${yy}-${mm}-${dd}`;
};

