// 统一日期清洗：支持 Date 对象、ISO 格式、斜杠格式、带星期/中文/字母的日期文本，始终输出标准 YYYY-MM-DD
export const cleanDate = (d) => {
  if (!d) return '';
  if (d instanceof Date || Object.prototype.toString.call(d) === '[object Date]') {
    if (isNaN(d.getTime())) return '';
    const yy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    return `${yy}-${mm}-${dd}`;
  }
  let str = String(d).trim();
  str = str.replace(/[\u4e00-\u9fa5a-zA-Z].*$/, '');
  str = str.replace(/[\/\.年]/g, '-').replace(/月/g, '').replace(/日/g, '');
  const match = str.match(/(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (!match) return '';
  const year = parseInt(match[1], 10);
  const month = parseInt(match[2], 10);
  const day = parseInt(match[3], 10);
  const dateObj = new Date(year, month - 1, day);
  if (isNaN(dateObj.getTime())) return '';
  if (dateObj.getFullYear() !== year || dateObj.getMonth() + 1 !== month || dateObj.getDate() !== day) return '';
  return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
};

// 格式化日期为 YY/MM/DD, 周X
export const formatWithDay = (d, lang) => {
  if (!d) return '';
  const c = cleanDate(d);
  if (!c) return '';
  const parts = c.split('-');
  if (parts.length !== 3) return c.substring(2).replace(/-/g, '/');

  const year = parseInt(parts[0], 10);
  const month = parseInt(parts[1], 1) - 1;
  const day = parseInt(parts[2], 10);
  const dateObj = new Date(year, month, day);

  if (isNaN(dateObj.getTime())) return c.substring(2).replace(/-/g, '/');

  const yy = parts[0].substring(2);
  const mm = parts[1];
  const dd = parts[2];
  const daysZh = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'];
  const daysEn = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  return `${yy}/${mm}/${dd}, ${lang === 'zh' ? daysZh[dateObj.getDay()] : daysEn[dateObj.getDay()]}`;
};

// Excel 导出日期格式 YYYY/MM/DD 周X
export const exportDateFormat = (d, lang) => {
  if (!d) return '';
  const c = cleanDate(d);
  if (!c) return '';
  const parts = c.split('-');
  if (parts.length !== 3) return c.replace(/-/g, '/');

  const year = parseInt(parts[0], 10);
  const month = parseInt(parts[1], 1) - 1;
  const day = parseInt(parts[2], 10);
  const dateObj = new Date(year, month, day);

  if (isNaN(dateObj.getTime())) return `${parts[0]}/${parts[1]}/${parts[2]}`;

  const yyyy = parts[0];
  const mm = String(parts[1]).padStart(2, '0');
  const dd = String(parts[2]).padStart(2, '0');
  const daysZh = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'];
  const daysEn = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  return `${yyyy}/${mm}/${dd} ${lang === 'zh' ? daysZh[dateObj.getDay()] : daysEn[dateObj.getDay()]}`;
};

// 短日期格式 YY/MM/DD
export const shortDate = (d) => {
  const c = cleanDate(d);
  return c ? c.substring(2).replace(/-/g, '/') : '';
};

// 格式化预计到达时间（距离/速度）
export const formatETA = (d, s) => {
  if (!d || !s || s <= 0) return '';
  const h = d / s;
  if (h < 0.1) return '< 5m';
  const hr = Math.floor(h);
  const m = Math.round((h - hr) * 60);
  return hr === 0 ? `${m}m` : m === 0 ? `${hr}h` : `${hr}h ${m}m`;
};

// 格式化高德地图时间（秒 -> Xh Ym）
export const formatAMapTime = (secs) => {
  if (!secs) return '';
  const h = Math.floor(secs / 3600);
  const m = Math.floor((secs % 3600) / 60);
  return h > 0 ? `${h}h ${m}m` : `${m}m`;
};

// Date 对象转 YYYY-MM-DD
export const getYYYYMMDD = (d) => {
  const yy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${yy}-${mm}-${dd}`;
};

// 根据日期字符串获取节假日名称
export const getHoliday = (dbDateStr) => {
  if (!dbDateStr) return null;
  const [yyyy, mm, dd] = dbDateStr.split('-');
  if (!yyyy || !mm || !dd) return null;
  const yearMap = CHINESE_HOLIDAYS[yyyy];
  return yearMap ? (yearMap[`${mm}-${dd}`] || null) : null;
};
